#include "stdafx.h"#include "Queue.h"#include "..\Lang.h"#include "..\Resource.h"////~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Структураtypedef struct : public SPROLOZ  {  char name[64];  int    nCode;  bool   bReal;  bool   bSelect;  } Queue_Goto;//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~int PressGoto(DefinePress)  {  Queue_Goto* p = (Queue_Goto*)s;  if ( *p->name == '.' || *p->name == '\0'  ) return 1;  //  static char szGoto[256];  if ( nCode == 0 )    {    if ( p->bReal )      {      lstrcpy( szGoto, p->name );      ::PostMsg( q.hWnd, p->btSendType, (LPARAM)szGoto);      }    return 0;    }  //  if ( nCode == 1 )    return 0;  //  if ( point.x == -1 && point.y == -1 )    {    if ( ( p->nCode & 0xff ) != nCode )      return 1;    }  else  if ( !::PtInRect( &p->mRect, point ) )    return 0;  //  if ( !p->bReal )    {    lstrcpy( szGoto, p->name );    ::PostMsg( q.hWnd, p->btSendType, (LPARAM)szGoto);    }  return 0;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Функция отображенияint PaintGoto(DefinePaint)  {  QueueP(Queue_Goto);  if ( ::IsMnemoStyle(MNEMO_EDIT) )    {    if ( lstrcmpi( "Null", p->name ) == 0 )      {      CMyPen pen(hDC, 0xFF, 2 );      pen.Rect(p->mRect);      }    else      {      //CMyFont font( hDC, NULL, 0xff );      //p->mRect.left = 0;      //if ( lstrcmpi( p->name, "5E_PD" ) == 0 )      //font.DrawS( p->mRect, p->name, DT_RIGHT );//      CMyPen pen(hDC, 0x80, 2 );//      pen.Rect(p->mRect);      }    }  //  if ( p->bSelect )    {    if ( IsCurrentTex( q.hWnd, p->name ) )      {      //int rop2 = SetROP2( hDC, R2_XORPEN );      //::InvertRect(  hDC, &p->mRect );      //::SetROP2( hDC, rop2 );      TransparentRect( hDC, p->mRect, 0xbd3000, 0xe0e0e0 );      }    }  //  return 1;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void AddGoto(DefineTegs)  {  AddQueueEx(Queue_Goto);  // Код, посылаемый в АРМ  p->btSendType = QUEUE_GOTO;  // Определение функции вывода  p->paint = &PaintGoto;  p->press = &PressGoto;  //  EDirect eDir = dirFree;  //  STegObj obj[] =    {    { 'R', "rect"  , &p->mRect },    { 'E', "rc"    , &p->mRect },    { 'N', "d"     , &eDir  },    { 'N', "dir"   , &eDir  },    { 'N', "direct", &eDir  },    { 'H', "code"  , &p->nCode },    { 'L', "real"  , &p->bReal },    { 'L', "select", &p->bSelect },    };  //  ::ParserObjScn( teg, obj, sizeof(obj)/sizeof(STegObj) );  //  StrCPY( p->name, teg[0].value, sizeof(p->name) );  //  if ( eDir != dirFree )    {    sprintf_s( def.m_szStr, 256, "<StatGotoX=%d,%d par0=%d par1=%d edge=1>",      p->mRect.left, p->mRect.top, p->mRect.right, p->mRect.bottom );    switch ( eDir )      {      case dirUp   :def.m_szStr[9] = 'U';break;      case dirDown :def.m_szStr[9] = 'D';break;      case dirLeft :def.m_szStr[9] = 'L';break;      case dirRight:def.m_szStr[9] = 'R';break;      }    }  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~